arguments.file_text:
@page "/"

<PageTitle>ShipmentTracker</PageTitle>

<h1>Shipment Tracker</h1>
<p class="lead">Track your shipments in real time.</p>

<div class="row mt-4">
    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Track a Shipment</h5>
                <div class="input-group">
                    <input type="text" class="form-control" placeholder="Enter tracking number (e.g. TRK-20260601-001)"
                           @bind="trackingNumber" @bind:event="oninput"
                           @onkeydown="HandleKeyDown" />
                    <button class="btn btn-primary" @onclick="TrackShipment" disabled="@string.IsNullOrWhiteSpace(trackingNumber)">
                        Track
                    </button>
                </div>
            </div>
        </div>
    </div>
</div>

@if (searched)
{
    <div class="row mt-4">
        <div class="col-md-8">
            @if (shipment is not null)
            {
                <div class="card">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@shipment.TrackingNumber</strong>
                        <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span>
                    </div>
                    <div class="card-body">
                        <div class="row">
                            <div class="col-md-6">
                                <p><strong>From:</strong> @shipment.Origin</p>
                                <p><strong>To:</strong> @shipment.Destination</p>
                                <p><strong>Recipient:</strong> @shipment.RecipientName</p>
                            </div>
                            <div class="col-md-6">
                                <p><strong>Description:</strong> @shipment.Description</p>
                                <p><strong>Shipped:</strong> @shipment.CreatedAt.ToString("MMM dd, yyyy")</p>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    <p><strong>Estimated Delivery:</strong> @shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</p>
                                }
                            </div>
                        </div>
                    </div>
                </div>
            }
            else
            {
                <div class="alert alert-warning">
                    No shipment found for tracking number <strong>@searchedNumber</strong>.
                </div>
            }
        </div>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string? trackingNumber;
    private string? searchedNumber;
    private ShipmentDto? shipment;
    private bool searched;

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dispatcher"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize(Roles = "Dispatcher")]

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <div class="input-group">
            <span class="input-group-text">Filter</span>
            <input type="text" class="form-control" placeholder="Search by tracking #, destination, or recipient..."
                   @bind="searchFilter" @bind:event="oninput" />
        </div>
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="statusFilter">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-3 text-end">
        <button class="btn btn-outline-primary" @onclick="LoadShipments">
            Refresh
        </button>
    </div>
</div>

@if (loading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null)
{
    <div class="alert alert-danger">Failed to load shipments.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Recipient</th>
                    <th>Status</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.RecipientName</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <select class="form-select form-select-sm" @bind="editingStatus">
                                    @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                            }
                            else
                            {
                                <span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span>
                            }
                        </td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <button class="btn btn-sm btn-success me-1" @onclick="() => SaveStatus(s)" disabled="@saving">
                                    Save
                                </button>
                                <button class="btn btn-sm btn-outline-secondary" @onclick="CancelEdit" disabled="@saving">
                                    Cancel
                                </button>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary" @onclick="() => StartEdit(s)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filter criteria.</div>
    }
}

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert @(statusSuccess ? "alert-success" : "alert-danger") mt-3 alert-dismissible">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private List<ShipmentDto>? shipments;
    private bool loading = true;
    private string? searchFilter;
    private string? statusFilter;
    private int? editingId;
    private ShipmentStatus editingStatus;
    private bool saving;
    private string? statusMessage;
    private bool statusSuccess;

    private IEnumerable<ShipmentDto> FilteredShipments
    {
        get
        {
            if (shipments is null) return [];

            var result = shipments.AsEnumerable();

            if (!string.IsNullOrWhiteSpace(searchFilter))
            {
                var filter = searchFilter.Trim();
                result = result.Where(s =>
                    s.TrackingNumber.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                    s.Destination.Contains(filter, StringComparison.OrdinalIgnoreCase) ||
                    s.RecipientName.Contains(filter, StringComparison.OrdinalIgnoreCase));
            }

            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var parsed))
            {
                result = result.Where(s => s.Status == parsed);
            }

            return result;
        }
    }

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        loading = true;
        shipments = await ShipmentService.GetAllShipmentsAsync();
        loading = false;
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingId = shipment.Id;
        editingStatus = shipment.Status;
    }

    private void CancelEdit()
    {
        editingId = null;
    }

    private async Task SaveStatus(ShipmentDto shipment)
    {
        saving = true;
        var success = await ShipmentService.UpdateShipmentStatusAsync(shipment.Id, editingStatus);

        if (success)
        {
            shipment.Status = editingStatus;
            statusMessage = $"Shipment {shipment.TrackingNumber} updated to {editingStatus}.";
            statusSuccess = true;
        }
        else
        {
            statusMessage = $"Failed to update shipment {shipment.TrackingNumber}.";
            statusSuccess = false;
        }

        editingId = null;
        saving = false;
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@attribute [Authorize]

<PageTitle>My Shipments</PageTitle>

<h1>My Shipments</h1>

<div class="row mb-3">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number"
                   @bind="trackingNumber" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="SearchShipment" disabled="@(string.IsNullOrWhiteSpace(trackingNumber) || searching)">
                Search
            </button>
        </div>
    </div>
</div>

@if (searching)
{
    <p><em>Searching...</em></p>
}
else if (searched)
{
    @if (shipment is not null)
    {
        <div class="card mb-4">
            <div class="card-header d-flex justify-content-between align-items-center">
                <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
                <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
            </div>
            <div class="card-body">
                <div class="row">
                    <div class="col-md-6">
                        <dl>
                            <dt>From</dt>
                            <dd>@shipment.Origin</dd>
                            <dt>To</dt>
                            <dd>@shipment.Destination</dd>
                            <dt>Recipient</dt>
                            <dd>@shipment.RecipientName</dd>
                        </dl>
                    </div>
                    <div class="col-md-6">
                        <dl>
                            <dt>Description</dt>
                            <dd>@shipment.Description</dd>
                            <dt>Shipped Date</dt>
                            <dd>@shipment.CreatedAt.ToString("MMMM dd, yyyy")</dd>
                            <dt>Estimated Delivery</dt>
                            <dd>
                                @if (shipment.EstimatedDelivery.HasValue)
                                {
                                    var daysLeft = (shipment.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                    <span>@shipment.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</span>
                                    @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
                                    {
                                        if (daysLeft > 0)
                                        {
                                            <span class="text-muted ms-2">(@daysLeft day@(daysLeft != 1 ? "s" : "") away)</span>
                                        }
                                        else if (daysLeft == 0)
                                        {
                                            <span class="text-success ms-2">(arriving today)</span>
                                        }
                                        else
                                        {
                                            <span class="text-danger ms-2">(overdue)</span>
                                        }
                                    }
                                }
                                else
                                {
                                    <span class="text-muted">Not yet estimated</span>
                                }
                            </dd>
                        </dl>
                    </div>
                </div>

                <h6 class="mt-3">Delivery Progress</h6>
                <div class="progress" style="height: 30px;">
                    <div class="progress-bar @GetProgressBarClass(shipment.Status)"
                         role="progressbar"
                         style="width: @(GetProgressPercent(shipment.Status))%"
                         aria-valuenow="@GetProgressPercent(shipment.Status)"
                         aria-valuemin="0" aria-valuemax="100">
                        @shipment.Status
                    </div>
                </div>
            </div>
        </div>
    }
    else
    {
        <div class="alert alert-warning">
            No shipment found for tracking number <strong>@searchedNumber</strong>. Please check and try again.
        </div>
    }
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string? trackingNumber;
    private string? searchedNumber;
    private ShipmentDto? shipment;
    private bool searched;
    private bool searching;

    private async Task SearchShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber))
            return;

        searching = true;
        searchedNumber = trackingNumber.Trim();
        shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
        searching = false;
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await SearchShipment();
    }

    private static int GetProgressPercent(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => 10,
        ShipmentStatus.PickedUp => 30,
        ShipmentStatus.InTransit => 55,
        ShipmentStatus.OutForDelivery => 80,
        ShipmentStatus.Delivered => 100,
        ShipmentStatus.Cancelled => 100,
        _ => 0
    };

    private static string GetProgressBarClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
