16.     .AddInteractiveServerComponents()
17.     .AddInteractiveWebAssemblyComponents()
18.     .AddAuthenticationStateSerialization(options =>
19.     {
20.         options.SerializeAllClaims = true;
21.     });
22. 
23. builder.Services.AddCascadingAuthenticationState();
24. builder.Services.AddScoped<IdentityRedirectManager>();
25. builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();
26. 
27. builder.Services.AddAuthentication(options =>
28.     {
29.         options.DefaultScheme = IdentityConstants.ApplicationScheme;
30.         options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
31.     })
32.     .AddIdentityCookies();
33. 
34. var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
35. builder.Services.AddDbContext<ApplicationDbContext>(options =>
36.     options.UseSqlite(connectionString));
37. builder.Services.AddDatabaseDeveloperPageExceptionFilter();
38. 
39. builder.Services.AddIdentityCore<ApplicationUser>(options =>
40.     {
41.         options.SignIn.RequireConfirmedAccount = true;
42.         options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
43.     })
44.     .AddRoles<IdentityRole>()
45.     .AddEntityFrameworkStores<ApplicationDbContext>()
46.     .AddSignInManager()
47.     .AddDefaultTokenProviders();
48. 
49. builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();
50. 
51. builder.Services.AddScoped<IShipmentService, ServerShipmentService>();
52. 
53. builder.Services.AddAuthorizationBuilder()
54.     .AddPolicy("DispatcherOnly", policy => policy.RequireRole("Dispatcher"));
55. 
56. var app = builder.Build();
57. 
58. using (var scope = app.Services.CreateScope())
59. {
60.     var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
61.     db.Database.Migrate();
62.     SeedData.Initialize(db);
63. }
64. 
