69.     app.UseMigrationsEndPoint();
70. }
71. else
72. {
73.     app.UseExceptionHandler("/Error", createScopeForErrors: true);
74. }
75. app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
76. app.UseAntiforgery();
77. 
